/* Night44: cosmetic-only spider witch atlas; 4 directions, walk and existing melee attack. */
(()=>{'use strict';const A=globalThis.NIGHT44={ready:false,error:null,frames:64,revision:44};const image=new Image(),faces=new WeakMap(),anchors=[];
function pose(e,t){let f=faces.get(e);if(!f){f={x:e.x,y:e.y,dir:0,moved:0};faces.set(e,f)}const dx=e.x-f.x,dy=e.y-f.y;
 if(Math.abs(dx)+Math.abs(dy)>.001){f.dir=Math.abs(dx)>Math.abs(dy)?(dx>0?1:3):(dy>0?0:2);f.moved=t}f.x=e.x;f.y=e.y;
 const attacking=e.cd>.2&&e.kb<=0;if(attacking&&globalThis.SH){const x=SH.pos.x-e.x,y=SH.pos.y-e.y;if(Math.hypot(x,y)<2)f.dir=Math.abs(x)>Math.abs(y)?(x>0?1:3):(y>0?0:2)}
 const frame=attacking?Math.max(0,Math.min(7,Math.floor((1-e.cd)*10))):(t-f.moved<180?Math.floor(t/110+(e.p||0))%8:0);
 return{row:f.dir+(attacking?4:0),col:frame,attacking,dir:f.dir};}
A.pose=pose;A.draw=(g,e,x,y,t,z)=>{if(!A.ready||e.t!=='n')return false;const p=pose(e,t),w=image.naturalWidth/8,h=image.naturalHeight/8;
 g.save();g.fillStyle='rgba(0,0,0,.28)';g.beginPath();g.ellipse(x,y,z*.85,z*.2,0,0,Math.PI*2);g.fill();g.drawImage(image,p.col*w,p.row*h,w,h,x-z*1.8,y-z*3.6*anchors[p.row*8+p.col],z*3.6,z*3.6);g.restore();return true};
image.onload=()=>{try{const w=image.naturalWidth/8,h=image.naturalHeight/8,c=document.createElement('canvas');c.width=Math.ceil(w);c.height=Math.ceil(h);const g=c.getContext('2d',{willReadFrequently:true});
 for(let r=0;r<8;r++)for(let col=0;col<8;col++){g.clearRect(0,0,c.width,c.height);g.drawImage(image,col*w,r*h,w,h,0,0,c.width,c.height);const d=g.getImageData(0,0,c.width,c.height).data;let fy=0;for(let y=0;y<c.height;y++)for(let x=0;x<c.width;x++)if(d[(y*c.width+x)*4+3]>=128)fy=Math.max(fy,y+1);if(!fy)throw Error('Khung quái rỗng');anchors.push(fy/c.height)}
 A.ready=true;}catch(e){A.error=String(e);console.warn('[NIGHT44]',A.error)}};image.onerror=()=>{A.error='Không tải được ngoại hình quái đêm'};
image.src='data:image/png;base64,';})();
